def unit_of_work(metadata=None, timeout=None):
    def wrapper_function(function):
        def wrapped_function(tx):
            tx.run("CALL dbms.setTXMetaData($metadata)", {"metadata": metadata})
            if timeout:
                tx.run("CALL dbms.transaction.begin($timeout)", {"timeout": timeout})
            try:
                result = function(tx)
                tx.run("CALL dbms.transaction.commit()")
                return result
            except:
                tx.run("CALL dbms.transaction.rollback()")
                raise
        return wrapped_function
    return wrapper_function

