def _wait_for_tasks(
    tasks: List[asyncio.Task[tuple[int, bytes]]], target_concurrency: int
) -> List[tuple[int, bytes]]:
    semaphore = asyncio.Semaphore(target_concurrency)

    results = []
    for task in tasks:
        with (yield from semaphore):
            result = yield from task
            results.append(result)

    return results

def _get_results(results: List[tuple[int, bytes]]) -> tuple[int, bytes]:
    exit_code = 0
    output = b""
    for result in results:
        exit_code |= result[0]
        output += result[1]

    return (exit_code, output)

