    target_concurrency: Target number of partitions to run concurrently
    """
    args = []
    for arg in varargs:
        args.extend(arg.split())

    if color:
        cmd = cmd + ('--color',)

    max_length = _max_length - len(cmd) - len(args)

    partitions = []
