def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            if lock:
                lock.acquire()
            try:
                result = cache.get(key(*args, **kwargs))
                if result is None:
                    result = func(*args, **kwargs)
                    cache.put(key(*args, **kwargs), result)
            finally:
                if lock:
                    lock.release()
            return result
        return wrapper
    return decorator
