            now = timer()
            def _wrapper():
                return func(*args, **kwargs)
            try:
                value, last_update = cache[args]
                if now - last_update > ttl:
                    del cache[args]
                    raise KeyError
                return value
            except KeyError:
                value = _wrapper()
                cache[args] = (value, now)
                return value

        def clear():
            cache.clear()

        wrapper.clear = clear
        return wrapper
    return decorator

