def extostr(cls, e, max_level=30, max_path_level=5):
    if max_level <= 0 or max_path_level <= 0:
        return ""
    tb = [frame for frame in traceback.extract_stack() if frame[2] not in ('decorator', 'builtin_function_or_method', 'method', 'method-wrapper', '<module>')]
    tb = tb[-max_level:]
    tb = [(f"File '{frame[0]}', line {frame[1]}, in {frame[2]}") for frame in tb]
    tb = [frame for frame in tb if frame.find('rdmolfiles.py') == -1]
    tb = "\n".join(tb)
    if isinstance(e, (ValueError, TypeError)):
        return e.__class__.__name__ + ": " + str(e) + "\n" + tb
    else:
        return str(e.__class__.__name__) + " (" + repr(e) + ")\n" + tb

