    """
    if not isinstance(context, dict):
        raise TypeError("context must be a dict, not " + str(type(context)))
    if not isinstance(context.get("error"), (list, tuple)):
        context["error"] = []
    context["error"].append({
        "index": self._get_error_index()
    })
    for d in self._get_data():
        if not isinstance(d, dict):
