            observer_schemas.append(krake.schemas.kubernetes.ObserverSchema(
                name=resource.meta.name,
                type="kubernetes",
                target=resource,
                trigger=krake.schemas.kubernetes.Trigger(
                    type="probe",
                    schedule=krake.schemas.kubernetes.Schedule(
