def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    if not many_params:
        return (sql, many_params)

    in_style = self.in_style
    out_style = self.out_style

    # convert in-style parameters to list of dictionaries
    in_params: List[Dict[Union[str, int], Any]] = []
    for params in many_params:
        if in_style == ParamsStyle.NAMED:
            if not isinstance(params, dict):
                raise TypeError("named parameters must be a mapping")
            in_params.append(params)
        elif in_style == ParamsStyle.FORMAT:
            if not isinstance(params, (list, tuple)):
                raise TypeError("formatted parameters must be an iterable")
            in_params.append(_format_params(params))
        elif in_style == ParamsStyle.PYFORMAT:
            if not isinstance(params, (list, tuple)):
                raise TypeError("pyformat parameters must be an iterable")
            in_params.append(_pyformat_params(params))
        else:
            in_params.append(_numeric_params(params))

    # convert to out-style parameters
    if out_style == ParamsStyle.NAMED:
        out_params = [[{k: v} for k, v in p.items()] for p in in_params]
    elif out_style == ParamsStyle.FORMAT:
        out_params = [[(k,) for k in p.keys()] for p in in_params]
    elif out_style == ParamsStyle.PYFORMAT:
        out_params = [
            [('{%s}' % k,) for k in p.keys()] for p in in_params]
    else:
        out_params = [[{} for _ in range(len(p))] for p in in_params]

    # convert query to out-style parameters
    out_sql = _format_query(sql, out_params)

    return (out_sql, out_params)

