def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for logical_path, content_file in inventory.path_map.items():
        if content_file.version <= version:
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(content_file.file_name)
    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Create an empty dictionary to store the logical path to content file map
    logical_path_map = {}

    # Iterate over the files in the inventory
    for file in inventory:
        # Check if the file is a content file
        if file.type == 'content':
            # Get the logical path of the file
            logical_path = file.logical_path

            # Check if the logical path is already in the dictionary
            if logical_path in logical_path_map:
                # If it is, add the content file to the set of content files for that logical path
                logical_path_map[logical_path].add(file)
            else:
                # If it's not, create a new set with the content file
                logical_path_map[logical_path] = {file}

    return logical_path_map

