def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    if "hashes" not in fixity or not isinstance(fixity["hashes"], dict):
        raise ValueError("Fixity block must have a 'hashes' key with a dictionary value.")

    for filename, hashval in fixity["hashes"].items():
        if filename not in manifest_files:
            raise ValueError(f"File '{filename}' not found in manifest.")
        if not isinstance(hashval, str) or not re.match(r"^[0-9a-f]{32}$", hashval):
            raise ValueError(f"Hash value for {filename} is not a 32-character hexadecimal string.")

