def absorb(self, args: Sequence[Expression]) -> List[Expression]:
    """
    Given an `args` sequence of expressions, return a new list of expression applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    absorb_dict: Dict[Expression, int] = defaultdict(int)
    for expr in args:
        if isinstance(expr, And):
            a, b = expr.args
            if a == b:
                absorb_dict[a] += 1
            elif a in absorb_dict and b in absorb_dict:
                continue
            else:
                absorb_dict[a] += 1
                absorb_dict[b] += 1
        elif isinstance(expr, Or):
            a, b = expr.args
            if a != b:
                absorb_dict[a] += 1
                absorb_dict[b] += 1
        elif isinstance(expr, Not):
            a = expr.args[0]
            if absorb_dict[a]:
                absorb_dict[a] -= 1
        elif isinstance(expr, Apply):
            function, *args = expr.args
            new_args = []
            for arg in args:
                if isinstance(arg, In):
                    in_function, *arg_args = arg.args
                    if in_function == function:
                        new_args.append(arg_args[0])
                else:
                    new_args.append(arg)
            if not new_args:
                continue
            elif len(new_args) == 1:
                if isinstance(new_args[0], Out):
                    absorb_dict[new_args[0].args[1]] += 1
            else:
                assert isinstance(function, UnaryOperation)
                " " 
                Chebyshev polynomials require both 'times' and 'compose' functions TO KNOW THE COMBINATION OF CHEBYSHEV POLYNOMIALS IS A CHEBYSHEV POLYNOMIAL
                " " 
                if function.args[0] == 'times':
                    absorb_dict[new_args[0]] += 1
                    absorb_dict[new_args[1]] += 1
                elif function.args[0] == 'compose':
                    absorb_dict[new_args[0]] += 1
                    absorb_dict[new_args[1]] += 1
                else:
                    raise NotImplementedError("Unimplemented function: " + str(function.args[0]))
        else:
            raise NotImplementedError("Unimplemented expression type: " + str(type(expr)))

    return [e for e, _ in absorb_dict.items() if e]

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def absorption(a, b):
        if a is None:
            return b
        if b is None:
            return a
        if a == 1 and b == 0:
            return 0
        if a == 0 and b == 1:
            return 1
        if a == 1 and b == 1:
            return 1
        if a == 0 and b == 0:
            return 1
        return None

    def negative_absorption(a, b):
        if a is None:
            return b
        if b is None:
            return a
        if a == 1 and b == 1:
            return 1
        if a == 1 and b == 0:
            return 0
        if a == 0 and b == 1:
            return 1
        if a == 0 and b == 0:
            return 0
        return None

    result = []
    for i, arg in enumerate(args):
        result.append(absorption(arg, result[i - 1] if i > 0 else None))
    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for i, arg in enumerate(args):
        if arg == 'A' or arg == 'B':
            if i > 0 and args[i-1] in ['&', '|']:
                if args[i-1] == '&' and arg == 'A':
                    continue
                elif args[i-1] == '|' and arg == 'B':
                    continue
        result.append(arg)
    return result

