def check_object_validity(self, obj, check_digests, show_warnings):
    if check_digests:
        if obj.parent_object:
            expected_digest = obj.parent_object.digest
        else:
            expected_digest = None
        if obj.digest != expected_digest:
            if show_warnings:
                print("Warning: object {} has digest {}, but expected digest {}".format(obj.name, obj.digest, expected_digest))
            return False
    return True

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """

    num_objects = 0
    good_objects = 0

    # Recursively traverse the hierarchy, starting from the current element
    for child in self:
        if isinstance(child, AbstractElement):
            num_objects += 1
            if child.validate_hierarchy(validate_objects, check_digests, show_warnings):
                good_objects += 1

    # If the current element is an object, validate it
    if isinstance(self, pyfosili.fopp.properties.ObjectProperty):
        if validate_objects:
            if not self.obj.is_valid():
                if show_warnings:
                    warning("Invalid object found: " + str(self.obj.type) + ": " + repr(self.obj))
                return False
        if check_digests:
            if not self.obj.is_digest_valid():
                if show_warnings:
                    warning("Object with invalid digest found: " + str(self.obj.type) + ": " + repr(self.obj))
                return False

    # Return the number of objects checked and the number of good objects found
    return num_objects, good_objects

