def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    size = size.upper()
    if not size:
        return 0
    if size[-1] == "B":
        size = size[:-1]
    if size[-1] in "KMGTP":
        value = size[:-1]
        modifier = size[-1]
    else:
        value = size
        modifier = ""
    value = float(value)
    if modifier == "K":
        value *= 1000
    elif modifier == "M":
        value *= 1000000
    elif modifier == "G":
        value *= 1000000000
    elif modifier == "T":
        value *= 1000000000000
    elif modifier == "P":
        value *= 1000000000000000
    return int(value)

