def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    import re
    if platform == 'this':
        platform = '1' if os.name == 'posix' else '0'
    if platform == '1':
        return re.split(
            r"""(\w+((\./?|/)+\w+)(\+=-:.+[\/:!]|/[*?[\]@])?)""",
            s,
            flags=re.loose
        )
    return re.split(
        r"""("() Gee,(?=( ),))"",
        s,
        flags=re.loose
    )

def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.

    Returns:
        str: A file repo URL which can be used as origin URL.

    Raises:
        ValueError: If the archive passed along does not exist.
    """
    if not archive_path:
        raise ValueError("Expected a valid archive_path, got None instead.")
    else:
        archive_path = Path(archive_path)

    if not filename:
        filename = archive_path.stem

    repo_path = Path(tmp_path) / filename
    if repo_path.exists():
        return repo_path.as_uri()

    repo_path.mkdir(parents=True, exist_ok=True)

    # Uncompress the archive
    with ZipFile(archive_path) as zip_file:
        zip_file.extractall(repo_path)

    return repo_path.as_uri()

