def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Check if commands is a string or a list
    if isinstance(commands, str):
        commands = [commands]

    # Check if args is a string or a dict
    if isinstance(args, str):
        args = {args}

    # Create a new environment if necessary
    env = env or os.environ.copy()

    # Set the current working directory if specified
    if cwd:
        env['PWD'] = cwd

    # Loop over the commands and run them
    for command in commands:
        if verbose:
            print(f"Running command: {command}")

        # Create a new process and execute the command
        process = subprocess.Popen(command.split(), stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=env)

        # Read the output and error streams
        output, error = process.communicate()

        # Print the output if desired
        if not hide_stderr and error:
            print(error.decode("utf-8"), end="")

        # Return the output and error streams
        yield output, error

