        return parse_xrd(document)

def parse_xrd(document: str) -> Dict:
    """
    Parse XRD format.
    """
    xml_root = ElementTree.fromstring(document)
    xrd = {"links": []}
    for link in xml_root.findall(".//{http://www.w3.org/1999/02/22-rdf-syntax-ns#}Description"):
        attrs = link.attrib
        xrd["links"].append({
            "rel": attrs["rel"],
            "href": attrs["href"],
            "type": attrs["type"],
        })
    return xrd

