def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    response = urlopen(handle)
    webfinger_doc = parseString(response.read())
    webfinger = {}
    for element in webfinger_doc.getElementsByTagName("XRD"):
        if element.hasAttribute("xmlns") and element.getAttribute("xmlns") == "http://docs.oasis-open.org/ns/xri/xrd-1.0":
            for node in element.getElementsByTagName("Link"):
                rel = node.getAttribute("rel")
                if rel in webfinger:
                    webfinger[rel] = []
                webfinger[rel].append(node.getAttribute("template"))
    return webfinger

