    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        spec_content = yaml.safe_load('')
    try:
        spec_dict = yaml.safe_load(spec_content)
    except yaml.YAMLError as exc:
        raise IRValidatorException('Invalid YAML content') from exc

    validation_errors = []
    for field in cls._required_fields:
        if field not in spec_dict:
            validation_errors.append(field)

    if len(validation_errors) > 0:
        raise IRValidatorException(f'Missing required fields: {",".join(validation_errors)}')

    return spec_dict

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise IRValidatorException("No YAML file provided")
    with open(yaml_file, 'r') as f:
        data = yaml.safe_load(f)
    missing_data = []
    for required_field in cls.REQUIRED_FIELDS:
        if required_field not in data:
            missing_data.append(required_field)
    if missing_data:
        raise IRValidatorException("Required fields missing in YAML file: {}".format(missing_data))
    return data

